public final class ScreenRectanglesLegacyChecks {
 private static java.lang.reflect.Field members;
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();members=JoinedDisplayPower.Group.class.getDeclaredField("members");members.setAccessible(true);net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new ResourceLocation("minecraft:screen_rectangles_reference"));JsonArray output=new JsonArray();for(String id:ScreenFamilyLegacyChecks.IDS){BlockAnimatedScreenSelector block=null;for(Block candidate:ModBlocks.BLOCKS)if(candidate.getRegistryName().getResourcePath().equals(id))block=(BlockAnimatedScreenSelector)candidate;for(IBlockState state:block.getBlockState().getValidStates())for(int layout=0;layout<8;layout++)for(boolean boundary:new boolean[]{false,true})output.add(sample(block,state,layout(layout),layout==7,boundary,false));}BlockAnimatedScreenSelector block=(BlockAnimatedScreenSelector)ModBlocks.ANIMATED_SCREEN_SELECTOR;for(int width:new int[]{1022,1023,1024,1025}){int[][] cells=new int[width][2];for(int i=0;i<width;i++)cells[i][0]=i;output.add(sample(block,block.getDefaultState(),cells,false,false,true));}String serialized=output.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte value:hash.digest(serialized.getBytes("UTF-8")))digest.append(String.format("%02x",value&255));if(!digest.toString().equals("11ac292041c061ede9cabd982e1b6eb273e88c6ec77a7d129977a12af3c045d6"))throw new AssertionError("Actual rectangles changed "+digest);JsonObject root=new JsonObject();root.addProperty("sha256",digest.toString());root.add("cases",output);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-rectangles-reference.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.write(path,root.toString().getBytes("UTF-8"));System.out.println("Actual Screen rectangles reference PASS cases="+output.size()+" sha256="+digest);}
 private static JsonObject sample(BlockAnimatedScreenSelector block,IBlockState state,int[][] cells,boolean barrier,boolean boundary,boolean originOnly)throws Exception{NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.chunkLimit=boundary;BlockPos origin=boundary?new BlockPos(15,80,15):new BlockPos(0,80,0);java.util.List<TileEntityAnimatedScreenSelector> tiles=new java.util.ArrayList<>();TileEntityAnimatedScreenSelector seed=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);world.states.put(origin,state);world.tiles.put(origin,seed);seed.setWorld(world);seed.setPos(origin);DisplayJoinGeometry.Basis basis=DisplayJoinGeometry.basis(seed,state);for(int i=0;i<cells.length;i++){BlockPos pos=origin.add(basis.steps[0].getX()*cells[i][0]+basis.steps[2].getX()*cells[i][1],basis.steps[0].getY()*cells[i][0]+basis.steps[2].getY()*cells[i][1],basis.steps[0].getZ()*cells[i][0]+basis.steps[2].getZ()*cells[i][1]);IBlockState placed=state;if(barrier&&i==cells.length-1)for(IBlockState candidate:block.getBlockState().getValidStates())if(candidate!=state){placed=candidate;break;}TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);tile.activation.mode=2;world.states.put(pos,placed);world.tiles.put(pos,tile);tile.setWorld(world);tile.setPos(pos);tiles.add(tile);}JsonObject out=new JsonObject();out.addProperty("id",block.getRegistryName().getResourcePath());out.addProperty("meta",block.getMetaFromState(state));out.addProperty("boundary",boundary);JsonArray points=new JsonArray(),queries=new JsonArray(),edit=new JsonArray(),power=new JsonArray();for(int i=0;i<tiles.size();i++){TileEntityAnimatedScreenSelector tile=tiles.get(i);BlockPos pos=tile.getPos();JsonArray point=new JsonArray();point.add(pos.getX());point.add(pos.getY());point.add(pos.getZ());point.add(block.getMetaFromState(world.states.get(pos)));point.add(world.isBlockLoaded(pos));points.add(point);if((!originOnly||i==0)&&world.isBlockLoaded(pos)){queries.add(i);edit.add(indices(tiles,DisplayEditGroups.members(tile)));JoinedDisplayPower.level(tile);java.util.List<?> group=tile.joinedDisplayPower==null?java.util.Collections.singletonList(tile):(java.util.List<?>)members.get(tile.joinedDisplayPower);power.add(indices(tiles,group));}}out.add("nodes",points);out.add("queries",queries);out.add("edit",edit);out.add("power",power);return out;}
 private static JsonArray indices(java.util.List<?> all,java.util.List<?> group){JsonArray result=new JsonArray();for(Object member:group)result.add(all.indexOf(member));return result;}
 private static int[][] layout(int index){switch(index){case 0:return new int[][]{{0,0}};case 1:return new int[][]{{0,0},{1,0}};case 2:return new int[][]{{0,0},{1,0},{2,0},{0,1},{1,1},{2,1}};case 3:return new int[][]{{0,0},{1,0},{2,0},{0,1},{0,2}};case 4:return new int[][]{{0,0},{1,0},{2,0},{0,1},{2,1},{0,2},{1,2},{2,2}};case 5:return new int[][]{{0,0},{2,0},{2,1},{3,1}};case 6:return new int[][]{{0,0},{1,0},{1,1},{2,1},{2,2}};default:return new int[][]{{0,0},{1,0},{0,1},{1,1}};}}
}
